import Foundation
import UIKit

class SettingsRootViewController : UITableViewController, UINavigationControllerDelegate {
  @IBOutlet weak var versionLabel: UILabel!
  @IBOutlet weak var coreVersionLabel: UILabel!
  
  override func viewDidLoad() {
    let versionManager = VersionManager.shared()
    
    versionLabel.text = versionManager.appVersion.userFacing
    coreVersionLabel.text = versionManager.coreVersion
    navigationController?.delegate = self
    if let navigationController = navigationController {
      navigationController(navigationController, willShow: self, animated: false)
    }
  }

  func navigationController(_ navigationController: UINavigationController,
                            willShow viewController: UIViewController, animated: Bool) {
    guard viewController.navigationItem.searchController == nil else { return }
    let results = DOLSettingsSearchResultsController(style: .insetGrouped)
    results.hostNavigationController = navigationController
    let search = UISearchController(searchResultsController: results)
    search.searchResultsUpdater = results
    search.searchBar.placeholder = "Search All Settings"
    search.obscuresBackgroundDuringPresentation = false
    results.owningSearchController = search
    viewController.definesPresentationContext = true
    viewController.navigationItem.searchController = search
    viewController.navigationItem.hidesSearchBarWhenScrolling = false
  }
  
  override func tableView(_ tableView: UITableView, didSelectRowAt indexPath: IndexPath) {
    tableView.deselectRow(at: indexPath, animated: true)
    
    if (indexPath.section == 0 && indexPath.row == 3) {
      UIApplication.shared.open(URL(string: "https://oatmealdome.me/dolphinios/")!)
    }
  }
  
  @IBAction func unwindToSettings( _ seg: UIStoryboardSegue) {}
}


