[{"title":"Enable Dual Core (speedup)","description":"Runs emulated CPU and GPU on separate threads for better performance.","path":"Settings › Config › General › Basic Settings","storyboard":"ConfigSettings","identifier":"SearchConfigGeneral","section":0,"row":0},{"title":"Enable Cheats","description":"Allows Action Replay and Gecko cheat codes to run in games when codes are enabled.","path":"Settings › Config › General › Basic Settings","storyboard":"ConfigSettings","identifier":"SearchConfigGeneral","section":0,"row":1},{"title":"Allow Mismatched Region Settings","description":"","path":"Settings › Config › General › Basic Settings","storyboard":"ConfigSettings","identifier":"SearchConfigGeneral","section":0,"row":2},{"title":"Change Discs Automatically","description":"","path":"Settings › Config › General › Basic Settings","storyboard":"ConfigSettings","identifier":"SearchConfigGeneral","section":0,"row":3},{"title":"Speed Limit","description":"Controls emulation speed relative to normal game speed.","path":"Settings › Config › General › Basic Settings","storyboard":"ConfigSettings","identifier":"SearchConfigGeneral","section":0,"row":4},{"title":"Fallback Region","description":"","path":"Settings › Config › General › Fallback Region","storyboard":"ConfigSettings","identifier":"SearchConfigGeneral","section":1,"row":0},{"title":"Use Built-In Database of Game Names","description":"","path":"Settings › Config › Interface › User Interface","storyboard":"ConfigSettings","identifier":"SearchConfigInterface","section":0,"row":0},{"title":"Download Game Covers from GameTDB.com","description":"","path":"Settings › Config › Interface › User Interface","storyboard":"ConfigSettings","identifier":"SearchConfigInterface","section":0,"row":1},{"title":"Confirm on Stop","description":"","path":"Settings › Config › Interface › Render Window","storyboard":"ConfigSettings","identifier":"SearchConfigInterface","section":1,"row":0},{"title":"Use Panic Handlers","description":"","pa