private final class DOLSettingsSearchResultsController: UITableViewController, UISearchResultsUpdating {
  weak var hostNavigationController: UINavigationController?
  weak var owningSearchController: UISearchController?
  private var query = ""
  private var groupNames: [String] = []
  private var groupedResults: [[DOLSettingsSearchEntry]] = []

  override init(style: UITableView.Style) {
    super.init(style: .insetGrouped)
  }

  required init?(coder: NSCoder) {
    super.init(coder: coder)
  }

  override func viewDidLoad() {
    super.viewDidLoad()
    tableView.rowHeight = UITableView.automaticDimension
    tableView.estimatedRowHeight = 90
    tableView.sectionHeaderHeight = UITableView.automaticDimension
    tableView.estimatedSectionHeaderHeight = 44
    tableView.keyboardDismissMode = .onDrag
  }

  func updateSearchResults(for searchController: UISearchController) {
    query = (searchController.searchBar.text ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
    groupNames = []
    groupedResults = []
    if !query.isEmpty {
      for entry in DOLSettingsSearchCatalog.entries where
          entry.title.localizedCaseInsensitiveContains(query) ||
          entry.description.localizedCaseInsensitiveContains(query) {
        if let sectionIndex = groupNames.firstIndex(of: entry.path) {
          groupedResults[sectionIndex].append(entry)
        } else {
          groupNames.append(entry.path)
          groupedResults.append([entry])
        }
      }
    }
    tableView.reloadData()
  }

  override func numberOfSections(in tableView: UITableView) -> Int {
    groupNames.count
  }

  override func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
    groupedResults[section].count
  }

  override func tableView(_ tableView: UITableView, viewForHeaderInSection section: Int) -> UIView? {
    let header = UITableViewHeaderFooterView(reuseIdentifier: nil)
    header.textLabel?.text = groupNames[section]
    header.textLabel?.numberOfLines = 0
    header.textLabel?.lineBreakMode = .byWordWrapping
    return header
  }

  private func highlighted(_ value: String) -> NSAttributedString {
    let text = NSMutableAttributedString(string: value)
    guard !query.isEmpty else { return text }
    let nsText = value as NSString
    var offset = 0
    while offset < nsText.length {
      let remaining = NSRange(location: offset, length: nsText.length - offset)
      let found = nsText.range(of: query, options: [.caseInsensitive, .diacriticInsensitive], range: remaining)
      if found.location == NSNotFound || found.length == 0 { break }
      text.addAttributes([.backgroundColor: UIColor.systemYellow, .foregroundColor: UIColor.black],
                         range: found)
      offset = found.location + found.length
    }
    return text
  }

  override func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
    let cell = tableView.dequeueReusableCell(withIdentifier: "DOLSearchResult") ??
        UITableViewCell(style: .subtitle, reuseIdentifier: "DOLSearchResult")
    let item = groupedResults[indexPath.section][indexPath.row]
    cell.textLabel?.numberOfLines = 0
    cell.textLabel?.attributedText = highlighted(item.title)
    cell.detailTextLabel?.numberOfLines = 0
    cell.detailTextLabel?.attributedText = highlighted(item.description)
    cell.accessoryType = .disclosureIndicator
    return cell
  }

  override func tableView(_ tableView: UITableView, didSelectRowAt indexPath: IndexPath) {
    tableView.deselectRow(at: indexPath, animated: true)
    let item = groupedResults[indexPath.section][indexPath.row]
    let storyboard = UIStoryboard(name: item.storyboard, bundle: nil)
    let target = storyboard.instantiateViewController(withIdentifier: item.identifier)
    owningSearchController?.isActive = false
    // Dismiss the keyboard/search presentation before navigating.
    DispatchQueue.main.async { [weak self] in
      guard let navigation = self?.hostNavigationController else { return }
      navigation.pushViewController(target, animated: true)
      guard let table = target as? UITableViewController else { return }
      DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) {
        table.loadViewIfNeeded()
        if item.section < table.tableView.numberOfSections &&
           item.row < table.tableView.numberOfRows(inSection: item.section) {
          table.tableView.scrollToRow(at: IndexPath(row: item.row, section: item.section),
                                      at: .middle, animated: true)
        }
      }
    }
  }
}
